## Why This Is Asked
Tests ability to reason about cross-cache coherence, race conditions, and real-world invalidation delays in a global system.

## Key Concepts
- Canonical cache: Redis; edge caches: Memcached
- Per-key invalidation messages with tenant scoping
- Stampede prevention via per-key locking (SET NX with TTL)
- Invalidation workflow: publish from Redis, consume to purge Memcached, optional refresh from Redis

## Code Example
```javascript
// write path (pseudo)
async function updatePrice(tenantId, key, newValue) {
  const lockKey = `lock:${tenantId}:${key}`;
  const got = await redis.set(lockKey, '1', { NX: true, PX: 30000 });
  if (!got) throw new Error('busy');
  await redis.set(`cache:${tenantId}:${key}`, newValue);
  await redis.publish(`inval:${tenantId}:${key}`, '');
  await redis.del(lockKey);
}

// invalidation service (pseudo)
subscriber.subscribe(`inval:${tenantId}:${key}`, async () => {
  await memcached.delete(`cache:${tenantId}:${key}`);
  // optional refresh: memcached.set(...) from Redis value
});
```

## Follow-up Questions
- How would you test correctness and monitor cross-region coherence?
- What are trade-offs of using Redis pub/sub versus a dedicated invalidation queue?

## Why This Is Asked

Tests understanding of a beginner-friendly CQRS/event-sourcing workflow with cross-service coordination, compensation patterns, and concrete read model projections.

## Key Concepts

- Append-only EventStore per aggregate root
- Simple saga orchestration with compensation logic
- Read model projection from event streams
- Event-driven communication between bounded contexts

## Code Example

```javascript
// Data contracts
class OrderPlaced { constructor(orderId, items, amount) { this.orderId = orderId; this.items = items; this.amount = amount; } }
class InventoryReserved { constructor(orderId) { this.orderId = orderId; } }
class PaymentAuthorized { constructor(orderId) { this.orderId = orderId; } }
class PaymentFailed { constructor(orderId, reason) { this.orderId = orderId; this.reason = reason; } }
class InventoryRejected { constructor(orderId, reason) { this.orderId = orderId; this.reason = reason; } }

// Append-only EventStore per order
class EventStore {
  constructor() { this.events = new Map(); }
  append(orderId, event) {
    if (!this.events.has(orderId)) this.events.set(orderId, []);
    this.events.get(orderId).push(event);
  }
  getEvents(orderId) { return this.events.get(orderId) || []; }
}

// Saga Orchestrator
class OrderSaga {
  constructor(eventStore, inventoryService, paymentService) {
    this.eventStore = eventStore;
    this.inventory = inventoryService;
    this.payment = paymentService;
  }
  async handle(event) {
    if (event instanceof OrderPlaced) {
      this.eventStore.append(event.orderId, event);
      const inventoryResult = await this.inventory.reserve(event.orderId, event.items);
      if (inventoryResult.success) {
        this.eventStore.append(event.orderId, new InventoryReserved(event.orderId));
        const paymentResult = await this.payment.authorize(event.orderId, event.amount);
        if (paymentResult.success) {
          this.eventStore.append(event.orderId, new PaymentAuthorized(event.orderId));
        } else {
          this.eventStore.append(event.orderId, new PaymentFailed(event.orderId, paymentResult.reason));
          this.compensate(event.orderId);
        }
      } else {
        this.eventStore.append(event.orderId, new InventoryRejected(event.orderId, inventoryResult.reason));
      }
    }
  }
  compensate(orderId) {
    const events = this.eventStore.getEvents(orderId);
    events.reverse().forEach(event => {
      if (event instanceof InventoryReserved) {
        this.inventory.release(orderId);
      }
    });
  }
}

// Read Model Projection
class OrderStatusProjection {
  constructor(eventStore) {
    this.eventStore = eventStore;
    this.orderStatus = new Map();
  }
  project(orderId) {
    const events = this.eventStore.getEvents(orderId);
    let status = 'Pending';
    events.forEach(event => {
      if (event instanceof PaymentAuthorized) status = 'Completed';
      else if (event instanceof PaymentFailed || event instanceof InventoryRejected) status = 'Failed';
    });
    this.orderStatus.set(orderId, status);
    return status;
  }
}
```

## Why This Is Asked
Assesses approach to scaling and reliability for multi-tenant ingestion, including shard strategy, geo-replication, and strong delivery guarantees under duress.

## Key Concepts
- Partitioning by tenant and topic for isolation
- Exactly-once semantics via transactional producers and idempotent consumers
- Geo-replication strategies (e.g., Kafka MirrorMaker, Pulsar geo-replication)
- Shard rebalance with offset reconciliation to avoid data loss
- Disaster recovery, failover, and monitoring under regional outages

## Code Example
```
```javascript
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ clientId: 'ingest', brokers: ['kafka1:9092','kafka2:9092','kafka3:9092'] });
const producer = kafka.producer({ transactionalId: 'ingest-transaction' });
async function write(tenant, topic, messages) {
  const tx = await producer.transaction();
  try {
    for (const m of messages) {
      await tx.send({ topic: `${tenant}.${topic}`, messages: [ { key: m.key, value: m.value } ]});
    }
    await tx.commit();
  } catch (e) {
    await tx.abort();
    throw e;
  }
}
```
